111	async fn collect_completion(
112	    stream: impl TextOutputStream,
113	    request_id: String,
114	    response_model: String,
115	    created: u64,
116	    ApiServerOptions {
117	        enable_log_requests,
118	        enable_prompt_tokens_details,
119	        ..
120	    }: ApiServerOptions,
121	    ResponseOptions {
122	        // Ignored: non-streaming responses always include usage.
123	        include_usage: _,
124	        // Ignored: non-streaming responses are collected before usage is attached.
125	        include_continuous_usage: _,
126	        prompt_only,
127	        echo,
128	        requested_logprobs,
129	        include_prompt_logprobs,
130	        return_token_ids,
131	        return_tokens_as_token_ids,
132	    }: ResponseOptions,
133	) -> Result<CompletionResponse, ApiError> {
134	    let collected = stream
135	        .collect_output()
136	        .await
137	        .map_err(|error| server_error!("completion stream failed: {}", error.to_report_string()))?;
138	    let finish_reason = collected.finish_reason.clone();
139	    let stop_reason = finish_reason
140	        .as_stop_reason()
141	        .map(|sr| serde_json::to_value(sr).expect("StopReason must serialize to JSON"));
142	
143	    let prompt_char_count = echo.as_ref().map(|prompt| text_len(prompt)).unwrap_or_default();
144	    let logprobs = if requested_logprobs.is_some() && prompt_only {
145	        let prompt = echo.as_deref().ok_or_else(|| {
146	            server_error!("prompt-only completion response missing echoed prompt")
147	        })?;
148	        Some(prompt_only_logprobs_to_openai(
149	            collected.prompt_logprobs.as_ref(),
150	            prompt,
151	            collected.prompt_token_ids.as_ref(),
152	            return_tokens_as_token_ids,
153	        )?)
154	    } else if requested_logprobs.is_some() {
155	        Some(collected_logprobs_to_openai(
156	            &collected,
157	            echo.is_some(),
158	            prompt_char_count,
159	            return_tokens_as_token_ids,
160	        )?)
161	    } else {
162	        None
163	    };
164	    let prompt_logprobs = if include_prompt_logprobs {
165	        Some(prompt_logprobs_to_maps(
166	            collected.prompt_logprobs.as_ref(),
167	            collected.prompt_token_ids.as_ref(),
168	            return_tokens_as_token_ids,
169	        )?)
170	    } else {
171	        None
172	    };
173	    let text = match &echo {
174	        None => collected.text,
175	        Some(prompt) if prompt_only => prompt.clone(),
176	        Some(prompt) => format!("{prompt}{}", collected.text),
177	    };
178	    let finish_reason = completion_finish_reason_to_openai(finish_reason)?.to_string();
179	    let usage = Usage::from_token_usage(collected.usage, enable_prompt_tokens_details);
180	
181	    if enable_log_requests {
182	        info!(
183	            model = %response_model,
184	            prompt_tokens = usage.prompt_tokens,
185	            output_tokens = usage.completion_tokens.unwrap_or(0),
186	            %finish_reason,
187	            "completion finished"
188	        );
189	    }
190	
191	    Ok(CompletionResponse {
192	        id: request_id,
193	        object: "text_completion".to_string(),
194	        created,
195	        model: response_model,
196	        choices: vec![CompletionChoice {
197	            index: 0,
198	            text,
199	            logprobs,
200	            finish_reason: Some(finish_reason),
201	            stop_reason,
202	            prompt_logprobs,
203	            token_ids: return_token_ids.then(|| collected.token_ids.clone()),
204	            prompt_token_ids: return_token_ids.then(|| collected.prompt_token_ids.to_vec()),
205	        }],
206	        usage: Some(usage),
207	        system_fingerprint: None,
208	        kv_transfer_params: collected.kv_transfer_params,
209	    })
210	}
