44	/// Build the `token_strs` vector when requested, via the tokenizer vocab.
45	fn token_strs(tokenizer: &vllm_text::tokenizer::DynTokenizer, ids: &[u32]) -> Vec<String> {
46	    // Unknown IDs yield "" — intentional; matches Python's convert_ids_to_tokens behaviour.
47	    ids.iter().map(|&id| tokenizer.id_to_token(id).unwrap_or_default()).collect()
48	}
