50	pub async fn tokenize(
51	    State(state): State<Arc<AppState>>,
52	    headers: HeaderMap,
53	    ValidatedJson(body): ValidatedJson<TokenizeRequest>,
54	) -> Response {
55	    let request_id = tokenize_request_id(&headers);
56	    let tokenizer = state.chat.text().tokenizer();
57	    let max_model_len = state.chat.engine_core_client().max_model_len();
58	
59	    let result = match body {
60	        // Completion form: encode the raw `prompt` string (no chat template).
61	        TokenizeRequest::Completion(req) => tokenize_completion(&state, &tokenizer, req),
62	        // Chat form: render `messages` through the template, then encode (see `tokenize_chat`).
63	        TokenizeRequest::Chat(req) => tokenize_chat(&state, &request_id, req).await,
64	    };
65	
66	    match result {
67	        Ok((tokens, want_strs)) => {
68	            let token_strs = want_strs.then(|| token_strs(&tokenizer, &tokens));
69	            Json(TokenizeResponse {
70	                count: tokens.len(),
71	                max_model_len,
