77	/// Classify a text-pipeline submit failure: request validation failures are
78	/// the client's fault and map to HTTP 400, mirroring the Python frontend.
79	/// Everything else stays an internal 500.
80	pub fn text_submit_error(context: &'static str, error: vllm_text::Error) -> ApiError {
81	    if is_request_validation_error(&error) {
82	        return invalid_request!("{error}");
83	    }
84	    server_error!("{}: {}", context, error.to_report_string())
85	}
86	
87	/// Like [`text_submit_error`], for the chat pipeline (which both wraps the
88	/// text errors and raises its own prompt-length variant).
89	pub fn chat_submit_error(context: &'static str, error: vllm_chat::Error) -> ApiError {
90	    match &error {
91	        vllm_chat::Error::PromptTooLong { .. } => invalid_request!("{error}"),
92	        vllm_chat::Error::Text(text_error) if is_request_validation_error(text_error) => {
93	            invalid_request!("{error}")
94	        }
